[
  {"speaker": "NARRATION", "text": "Ehehehehe"},
  {"speaker": "character1", "text": "OH, HACHIKEN-KUN. YOU FINISHED WITH CLUB ALREADY?"},
  {"speaker": "character2", "text": "WHAT ARE YOU GUYS DOING!?"},
  {"speaker": "NARRATION", "text": "WHAT ARE YOU GUYS DOING!?"}
]

[
  {"speaker": "UNKNOWN", "text": "A young woman's tears are sure to lead a young man astray... Something definitely happened, but Hachiken is left wondering..."},
  {"speaker": "UNKNOWN", "text": "Click"},
  {"speaker": "UNKNOWN", "text": "What the heck happened...?"}
]

[
  {"speaker": "NARRATION", "text": "AND I WAS UNDER THE IMPRESSION THAT YOU DIDN'T EITHER."},
  {"speaker": "NARRATION", "text": "I DON'T BELIEVE IN SUCH RUMORS."},
  {"speaker": "NARRATION", "text": "DO YOU WANT TO SEE THIS MOVIE WITH ME?"}
]

[
  {"speaker": "character1", "text": "Hey Mongrel! I'll give ya 100 yen if ya eat this cigarette."},
  {"speaker": "character2", "text": "Gahaha! Bottom's up! Really?!"},
  {"speaker": "NARRATION", "text": "Try to run and you'll be sleeping with the fishes."},
  {"speaker": "character1", "text": "If another devil shows up, we'll call you."}
]

[
  {"speaker": "NARRATION", "text": "Well, normality's just a dream for us though."},
  {"speaker": "character1", "text": "That people normally eat bread with jam spread all over it."},
  {"speaker": "NARRATION", "text": "The other day I heard,"},
  {"speaker": "character1", "text": "I doubt I'll pay off this debt before I die."}
]

[
  {"speaker": "NARRATION", "text": "IF I COULD GET ANY WISH GRANTED, I'D WANNA BE WITH A GIRL BEFORE I DIE..."},
  {"speaker": "UNKNOWN", "text": "WHIMPER"},
  {"speaker": "NARRATION", "text": "...I'M GONNA DIE SINGLE AREN'T I?"},
  {"speaker": "UNKNOWN", "text": "NOT LIKE I COULD BRING A GIRL BACK TO THIS SHITSHACK. DON'T HAVE THE CASH TO BE DATIN' EITHER."}
]

[
  {"speaker": "UNKNOWN", "text": "WOAH!!"},
  {"speaker": "NARRATION", "text": "If you don't make this month's payment, we'll string you up..."},
  {"speaker": "UNKNOWN", "text": "If you can't do it, we'll cut you up and sell the pieces."},
  {"speaker": "character1", "text": "Boy. Begging, whoring, I don't care how, but you've got till tomorrow to get 7000 grand."}
]

[
  {"speaker": "NARRATION", "text": "A WOUND..."},
  {"speaker": "UNKNOWN", "text": "YOU'RE GONNA DIE TOO?"}
]

[
  {"speaker": "character1", "text": "I DON'T WANNA DIE EITHER..."},
  {"speaker": "character2", "text": "I'LL HELP YOU... SO NOW YOU GOTTA HELP ME."},
  {"speaker": "NARRATION", "text": "HOW'S ABOUT HIRIN' ME AS A DEVIL HUNTER?"}
]

[
  {"speaker": "UNKNOWN", "text": "I CAN'T SLEEP, SO I KEEP THINKIN' ABOUT THE DEBT, WHICH JUST MAKES IT WORSE..."},
  {"speaker": "UNKNOWN", "text": "SO HUNGRY I CAN'T SLEEP..."},
  {"speaker": "NARRATION", "text": "...I'VE DECIDED."},
  {"speaker": "UNKNOWN", "text": "IF I SLEEP TONIGHT, I'M GONNA DREAM ABOUT..."}
]

[
  {"speaker": "character1", "text": "So we made a contract with a devil like you did."},
  {"speaker": "character2", "text": "We wanted to get stronger to make more money, us Yakuza."}
]

[
  {"speaker": "UNKNOWN", "text": "DEATH!"},
  {"speaker": "UNKNOWN", "text": "AND WHAT I WANTED WAS DEVIL HUNTERS..."},
  {"speaker": "UNKNOWN", "text": "WHAT WE WANTED WAS A DEVIL'S POWER..."},
  {"speaker": "NARRATION", "text": "DO NOT MIRROR."}
]

[
  {"speaker": "character1", "text": "POCHITA..."},
  {"speaker": "character2", "text": "...you took over my body, huh?"},
  {"speaker": "NARRATION", "text": "Meanwhile..."}
]

[
  {"speaker": "UNKNOWN", "text": "SHOW ME MORE OF YOUR DREAMS."},
  {"speaker": "NARRATION", "text": "MY WOUNDS..."},
  {"speaker": "POCHITA!", "text": "POCHITA!"}
]

[
  {"speaker": "NARRATION", "text": "POCHITA!"},
  {"speaker": "UNKNOWN", "text": "POCHITA!"}
]

[
  {"speaker": "UNKNOWN", "text": "HMM?"},
  {"speaker": "character1", "text": "YOU'RE STILL ALIVE AFTER GETTING CUT TO PIECES?! GROSS!"},
  {"speaker": "character2", "text": "I REALLY HATE YOU DEVIL HUNTERS!"},
  {"speaker": "NARRATION", "text": "YOU GUYS! EAT HIM UP!"}
]

[
  {"speaker": "character1", "text": "ONE'S STILL ALIVE."},
  {"speaker": "character2", "text": "HMPH..."},
  {"speaker": "NARRATION", "text": "YOU'RE A STRANGE ONE."},
  {"speaker": "character1", "text": "YOU DON'T SMELL LIKE A DEVIL OR A HUMAN."}
]

[
  {"speaker": "character1", "text": "DID YOU DO THIS?"},
  {"speaker": "NARRATION", "text": "HOLD ME..."},
  {"speaker": "character2", "text": "H-..."},
  {"speaker": "NARRATION", "text": "..."}
]

[
  {"speaker": "NARRATION", "text": "NO, YOU CAN TELL TAKE-OVERS BY LOOKING AT THEIR FACE."},
  {"speaker": "character2", "text": "COULD HE BE TAKEN OVER BY A DEVIL?"},
  {"speaker": "character1", "text": "IT'S A HUMAN..."},
  {"speaker": "NARRATION", "text": "WOAH!!"}
]

[
  {"speaker": "character1", "text": "WHAT ARE YOU TRYING TO SAY..."},
  {"speaker": "character2", "text": "YOU KNOW HIM?"},
  {"speaker": "NARRATION", "text": "THE GUN DEVIL WANTS YOUR HEART."}
]

[
  {"speaker": "UNKNOWN", "text": "WOAH!!"},
  {"speaker": "NARRATION", "text": "The bullet..."},
  {"speaker": "UNKNOWN", "text": "...hit the target."}
]

[
  {"speaker": "character1", "text": "CHAK"},
  {"speaker": "character2", "text": "HNG!"},
  {"speaker": "NARRATION", "text": "..."}
]

[
  {"speaker": "UNKNOWN", "text": "SKSHH"},
  {"speaker": "UNKNOWN", "text": "KRAKKRAKKRAK"},
  {"speaker": "UNKNOWN", "text": "KTHUMP"}
]

[
  {"speaker": "character1", "text": "Thank you for your concern."},
  {"speaker": "character2", "text": "Hey, man."},
  {"speaker": "NARRATION", "text": "Nah, that wasn't wrestling."},
  {"speaker": "character3", "text": "I heard you were wrestling with Porkchop Marvin again."}
]

[
  {"speaker": "UNKNOWN", "text": "forty-two westwood, Los Angeles..."},
  {"speaker": "UNKNOWN", "text": "CHAK"},
  {"speaker": "NARRATION", "text": "Meanwhile..."}
]

[
  {"speaker": "NARRATION", "text": "When it's your time to go, make sure you're surrounded by others."},
  {"speaker": "UNKNOWN", "text": "Grandpa?"},
  {"speaker": "NARRATION", "text": "Mr. Itadori?"},
  {"speaker": "NARRATION", "text": "Yes? How may I help you?"}
]

[
  {"speaker": "NARRATION", "text": "This is the fourth floor!"},
  {"speaker": "UNKNOWN", "text": "Ita-dori?!"},
  {"speaker": "character1", "text": "ASH"}
]

[
  {"speaker": "character1", "text": "I THINK YOU DIED PEACEFULLY, GRANDPA."}
]

[
  {"speaker": "NARRATION", "text": "WHAT'S UP WITH THIS?"},
  {"speaker": "character1", "text": "I'M NOT SURE IF YOU SHOULD BE WORRIED ABOUT OTHER PEOPLE RIGHT NOW..."},
  {"speaker": "character2", "text": "KREAK"},
  {"speaker": "NARRATION", "text": "...HAS BEEN SET!"}
]

[
  {"speaker": "UNKNOWN", "text": "I've got a student watching, so..."},
  {"speaker": "UNKNOWN", "text": "I hope you don't mind if I show off a little."},
  {"speaker": "character1", "text": "Those aren't souvenirs."},
  {"speaker": "character2", "text": "They're for me to eat on the bullet train home."}
]

[
  {"speaker": "UNKNOWN", "text": "BUT THAT DOESN'T MATTER TO ME."},
  {"speaker": "UNKNOWN", "text": "WHOOOM!"}
]

[
  {"speaker": "NARRATION", "text": "SUGISAWA HOSPITAL"},
  {"speaker": "ITADORI", "text": "It's all my fault..."},
  {"speaker": "UNKNOWN", "text": "The doctors say he's fine, but..."},
  {"speaker": "ITADORI", "text": "How is Iguchi doing?"}
]

[
  {"speaker": "NARRATION", "text": "There's somewhere I need to go."},
  {"speaker": "NARRATION", "text": "I'll see ya later."},
  {"speaker": "NARRATION", "text": "Who passed away?"},
  {"speaker": "NARRATION", "text": "Are there a lot of casualties with curses like this?"}
]

[
  {"speaker": "UNKNOWN", "text": "Hey there, apothecary."},
  {"speaker": "UNKNOWN", "text": "Chii chii chii (insect noise)"},
  {"speaker": "UNKNOWN", "text": "Chii chii chii (insect noise)"},
  {"speaker": "NARRATION", "text": "Insect noise..."}
]

[
  {"speaker": "character2", "text": "TODAY IS OUR LADY'S WEDDING DAY."},
  {"speaker": "character1", "text": "YOU CAN'T SELL YOUR WARES."},
  {"speaker": "UNKNOWN", "text": "HEY."},
  {"speaker": "NARRATION", "text": "SFX: CLACK!"}
]

[
  {"speaker": "UNKNOWN", "text": "AH-HA..."},
  {"speaker": "UNKNOWN", "text": "...."},
  {"speaker": "NARRATION", "text": "SFX: AH HA HA HA"}
]

[
  {"speaker": "character1", "text": "WHY ARE YOU TAKING SO LONG TO PUT AWAY THE OIL? HURRY UP!"},
  {"speaker": "character2", "text": "I'LL GET IT DONE RIGHT AWAY."},
  {"speaker": "NARRATION", "text": "YES, MA'AM..."},
  {"speaker": "character2", "text": "MY GOODNESS."}
]

[
  {"speaker": "NARRATION", "text": "Lady Mao is being wed to Lord Shiono."},
  {"speaker": "UNKNOWN", "text": "YES, YES."}
]

[
  {"speaker": "NARRATION", "text": "SFX: CLICK"},
  {"speaker": "NARRATION", "text": "SFX: THUD"},
  {"speaker": "NARRATION", "text": "character1: !"},
  {"speaker": "NARRATION", "text": "character2: ?"}
]

[
  {"speaker": "UNKNOWN", "text": "UNCLE."},
  {"speaker": "NARRATION", "text": "SFX: AH HA HA HA HA"},
  {"speaker": "NARRATION", "text": "SFX: CHII CHII CHII (INSECT NOISE)"}
]

[
  {"speaker": "character1", "text": "KAYO!"},
  {"speaker": "character2", "text": "M-MISS SATO!"},
  {"speaker": "NARRATION", "text": "WHAT IN THE WORLD ARE YOU DOING AT A TIME LIKE THIS?!"},
  {"speaker": "character3", "text": "UM, THIS IS..."}
]

[
  {"speaker": "NARRATION", "text": "WELL, BUT, EVEN IF I TELL THEM THEY WON'T LISTEN TO ME ANYHOW..."},
  {"speaker": "UNKNOWN", "text": "OUCH!"},
  {"speaker": "NARRATION", "text": "I'M SORRY..."},
  {"speaker": "NARRATION", "text": "A GUY FROM THE \"NEWLY ESTABLISHED UNIT\"?"}
]

[
  {"speaker": "UNKNOWN", "text": "WHERE ARE YOU HEADED?"}
]

[
  {"speaker": "UNKNOWN", "text": "Okay, this is good."},
  {"speaker": "character1", "text": "Um... right here is okay?"},
  {"speaker": "NARRATION", "text": "Here, okay?"}
]

[
  {"speaker": "NARRATION", "text": "...and then..."},
  {"speaker": "UNKNOWN", "text": "...the door..."},
  {"speaker": "UNKNOWN", "text": "...opened..."}
]

[
  {"speaker": "NARRATION", "text": "THE FASTEST WAY FOR ME TO RISE IN THE RANKS OF THE MARTIAL ARTS MASTERS AT THIS POINT IN TIME..."},
  {"speaker": "UNKNOWN", "text": "...IS TO SLAY YOU."},
  {"speaker": "NARRATION", "text": "MIYAMOTO MUSASHI."}
]

[
  {"speaker": "UNKNOWN", "text": "OH, OH?"},
  {"speaker": "UNKNOWN", "text": "IMPATIENCE WON'T GET YOU WALKING AGAIN."},
  {"speaker": "UNKNOWN", "text": "HMPH!"},
  {"speaker": "UNKNOWN", "text": "TAKEZO!"}
]

[
  {"speaker": "NARRATION", "text": "Otsu will stay here by your side."},
  {"speaker": "UNKNOWN", "text": "Eh."},
  {"speaker": "NARRATION", "text": "Listen, Musashi."}
]
